// =====================================================================
// parse-mensagem — normaliza o payload cru da Meta em campos simples.
// =====================================================================
//
// ESTRUTURA ASSUMIDA (WhatsApp Cloud API, campo de webhook "messages"):
//
//   {
//     object: "whatsapp_business_account",
//     entry: [{
//       changes: [{
//         value: {
//           metadata: { phone_number_id, display_phone_number },
//           contacts: [{ profile: { name }, wa_id }],
//           messages: [{
//             from: "5521989511871",   // sem "+"
//             id: "wamid....",
//             type: "text" | "image" | ...,
//             text:  { body: "..." },
//             image: { id: "<media_id>", mime_type, sha256 }
//           }]
//         }
//       }]
//     }]
//   }
//
// O WhatsApp Trigger do n8n, dependendo da versão, entrega esse envelope
// completo OU já desembrulhado em `value`. As duas formas são tratadas
// abaixo — se o seu n8n entregar num formato diferente, olhe a saída crua
// do trigger e ajuste `extrairValue()`.

// A Meta manda webhooks de status (sent/delivered/read) no MESMO campo
// "messages". Sem o filtro abaixo, cada resposta do bot dispararia o
// workflow de novo, em loop.
function extrairValue(body) {
  if (!body || typeof body !== 'object') return null;
  const doEnvelope = body?.entry?.[0]?.changes?.[0]?.value;
  if (doEnvelope) return doEnvelope;
  if (body.messages || body.statuses || body.metadata) return body;
  return null;
}

// A Meta entrega o número sem "+" (5521989511871); o banco guarda em E.164.
function paraE164(numero) {
  const digitos = String(numero ?? '').replace(/\D/g, '');
  return digitos ? '+' + digitos : null;
}

// Gotcha conhecido de números brasileiros: a Meta às vezes entrega celulares
// sem o 9º dígito (+5521989511871 chega como +552189511871). Geramos a outra
// variante para o SELECT tentar as duas — senão o vendedor "não existe".
function varianteNonoDigito(e164) {
  if (!e164 || !e164.startsWith('+55')) return null;
  const resto = e164.slice(3); // DDD + número
  if (resto.length === 11 && resto[2] === '9') {
    return '+55' + resto.slice(0, 2) + resto.slice(3); // tira o 9
  }
  if (resto.length === 10) {
    return '+55' + resto.slice(0, 2) + '9' + resto.slice(2); // põe o 9
  }
  return null;
}

const saida = [];

for (const item of $input.all()) {
  const value = extrairValue(item.json);
  if (!value) continue;

  const mensagem = value?.messages?.[0];
  if (!mensagem) continue; // status callback ou evento sem mensagem: ignora

  const tipo = mensagem.type ?? 'desconhecido';
  const numeroE164 = paraE164(mensagem.from);

  saida.push({
    json: {
      // Número normalizado, usado para achar o vendedor no banco.
      numero_remetente: numeroE164,
      // Variante com/sem 9º dígito (cai no mesmo valor quando não se aplica,
      // para o IN ($1, $2) do SELECT continuar válido).
      numero_remetente_variante: varianteNonoDigito(numeroE164) ?? numeroE164,
      // Número exatamente como a Meta mandou — é o que usamos para responder.
      numero_remetente_raw: mensagem.from ?? null,

      tipo_mensagem: tipo,
      texto: tipo === 'text' ? (mensagem.text?.body ?? null) : null,
      // Mesmo texto em minusculas e sem espaco nas pontas — e o que o
      // node rotear-comando-global compara pra achar o comando "menu".
      // String vazia (nunca null) pra comparacao no Switch ser simples.
      texto_normalizado: tipo === 'text'
        ? (mensagem.text?.body ?? '').trim().toLowerCase()
        : '',
      media_id: tipo === 'image' ? (mensagem.image?.id ?? null) : null,

      // Resposta de um Reply Button. Estrutura assumida do payload:
      //   messages[0] = {
      //     type: "interactive",
      //     interactive: { type: "button_reply", button_reply: { id: "abrir_refazer_imagem", title: "..." } }
      //   }
      // botao_id fica null para qualquer mensagem que não seja essa.
      botao_id: tipo === 'interactive' ? (mensagem.interactive?.button_reply?.id ?? null) : null,

      // Resposta de uma LISTA interativa (menu global ou lista de refazer
      // imagem). Estrutura:
      //   interactive: { type: "list_reply", list_reply: { id: "menu_recomecar", ... } }
      // Fica separado de botao_id de proposito: rotear-comando-global compara
      // os dois campos contra rotas diferentes.
      lista_id: tipo === 'interactive' ? (mensagem.interactive?.list_reply?.id ?? null) : null,

      // Número DO BOT que recebeu a mensagem. Evita ter que colar o
      // phone_number_id à mão em cada node de envio.
      phone_number_id: value?.metadata?.phone_number_id ?? null,

      nome_contato: value?.contacts?.[0]?.profile?.name ?? null,
      wamid: mensagem.id ?? null
    }
  });
}

// Array vazio encerra a execução aqui (caso dos status callbacks).
return saida;

