// =====================================================================
// montar-url-foto-original — monta a URL pública da foto original que o
// node anterior (upload-foto-original-storage) acabou de subir.
// =====================================================================
//
// Este node NÃO faz upload. O upload é do HTTP Request nativo anterior —
// ver a nota daquele node: Buffer dentro de Code node não sobrevive ao RPC
// do Task Runner e chegava corrompido no Storage.
//
// A URL é derivada do campo `Key` que o Supabase devolve na resposta do
// upload ("<bucket>/<caminho>"), que é a fonte de verdade do que realmente
// foi gravado — assim a URL salva no banco nunca diverge do arquivo real.
// O fallback só existe caso a resposta venha vazia, e repete a mesma regra
// de extensão usada na expressão de URL do node de upload.

const SUPABASE_URL = $env.SUPABASE_URL;
const BUCKET = $env.SUPABASE_STORAGE_BUCKET || 'listing-photos';

const listingId = $('criar-listing').first().json.id;
const key = $json.Key || $json.key || null;

let caminho;
if (key) {
  caminho = key.startsWith(BUCKET + '/') ? key.slice(BUCKET.length + 1) : key;
} else {
  const mime = $('baixar-foto').first().binary.data.mimeType || 'image/jpeg';
  const extensao = mime.includes('png') ? 'png' : 'jpg';
  caminho = `${listingId}/original.${extensao}`;
}

return [{
  json: {
    listing_id: listingId,
    original_photo_storage_url: `${SUPABASE_URL}/storage/v1/object/public/${BUCKET}/${caminho}`
  }
}];

