const resposta = $json;
const candidato = resposta.candidates?.[0];
const chunks = candidato?.groundingMetadata?.groundingChunks ?? [];
const texto = (candidato?.content?.parts ?? []).map(p => p.text).filter(Boolean).join('\n');
const confiante = chunks.length > 0 && texto.trim().length > 0;

return [{
  json: {
    confiante,
    descricao_base: texto,
    fonte: 'busca',
    nome_produto: $('parse-mensagem').first().json.texto
  }
}];

parameters.jsonBody:
={
  "contents": [{
    "parts": [{
      "text": "Você é um redator de anúncios do Mercado Livre. Escreva um anúncio para o produto "{{ JSON.stringify($json.nome_produto).slice(1, -1) }}" usando SOMENTE as informações factuais abaixo como base — NÃO invente nenhum dado numérico específico (peso, dimensão, capacidade, voltagem, certificação) que não esteja explicitamente nas informações abaixo; se não houver confirmação de um dado, simplesmente omita-o.

Informações factuais sobre o produto (fonte: {{ JSON.stringify($json.fonte).slice(1, -1) }}):
{{ JSON.stringify($json.descricao_base).slice(1, -1) }}

Escreva:
(1) um TÍTULO de venda com NO MÁXIMO 60 caracteres — limite rígido do Mercado Livre, não ultrapasse;
(2) uma DESCRICAO estruturada em EXATAMENTE estas 3 seções, cada uma com um cabeçalho em maiúsculas, nesta ordem:
SOBRE O PRODUTO — um parágrafo de abertura apresentando o produto.
CARACTERÍSTICAS — lista do que é visível/confirmado pelas informações factuais acima (nunca um número que não esteja lá).
COMO USAR — passo a passo funcional de uso.
NÃO inclua nenhuma seção de garantia ou envio — isso é adicionado separadamente, fora do seu texto.

Além disso, gere PALAVRAS-CHAVE de busca pro Mercado Livre: uma lista de 12 a 18 termos/expressões curtas relevantes pra esse produto (sinônimos, nomes alternativos, categoria, uso), separados por espaço, tudo em minúsculas, sem pontuação. Baseie-se só nas informações factuais fornecidas — não invente característica nem categoria que não esteja implícita no que foi dado.

Responda apenas com um JSON no formato {"titulo": "...", "descricao": "...", "palavras_chave": "termo1 termo2 termo3 ..."}, sem markdown, sem texto fora do JSON. O campo palavras_chave deve ser uma STRING única com os termos separados por espaço, nunca um array."
    }]
  }],
  "generationConfig": { "responseMimeType": "application/json" }
