const GARANTIA_ENVIO = 'GARANTIA E ENVIO\nProduto verificado antes da postagem. Envio rápido com embalagem protegida.\nEm caso de dúvidas, entre em contato pelo canal de mensagens do anúncio para atendimento ágil.';

const raw = $json.candidates?.[0]?.content?.parts?.[0]?.text ?? '{}';
let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  parsed = {};
}

const titulo = (parsed.titulo || 'Produto à venda').slice(0, 60);
const descricaoBase = parsed.descricao || 'Não foi possível gerar a descrição automaticamente — edite manualmente.';
const descricao = `${descricaoBase}\n\n${GARANTIA_ENVIO}`;

// palavras_chave vem no MESMO JSON do Gemini (nenhuma chamada extra).
// Nao e persistido no Postgres nesta rodada — segue só na execução, até a
// mensagem envio-palavras-chave. Pra guardar, ver nota em docs/data-model.md.
const palavrasChave = (parsed.palavras_chave || '').toString().trim()
  || 'não foi possível gerar as palavras-chave automaticamente — edite manualmente.';

return [{ json: { titulo, descricao, palavras_chave: palavrasChave } }];

const row = $('atualizar-listing-titulo-descricao').first().json;

const cc = $('buscar-vendedor').first().json.conversation_context;
const contexto = typeof cc === 'string' ? JSON.parse(cc || '{}') : (cc || {});

return [{
  json: {
    listing_id: row.id,
    generated_title: row.generated_title,
    generated_description: row.generated_description,
    original_photo_storage_url: row.original_photo_url,
    nome_produto: contexto.nome_produto
  }
}];

// =====================================================================
// gerar-prompts-gpt — manda o esqueleto das 8 cenas + o anúncio já
// gerado (título/descrição) pro GPT, pede de volta um prompt customizado
// por cena, em JSON. Copiado (estrutura do prompt e ESQUELETOS_CENAS) de
// ml_test/test_pipeline_gpt_gemini.py, função gerar_prompts_customizados.
// =====================================================================
//
// Por que Code node e não HTTP Request node: o texto da instrução inclui
// as 8 regras_fixas inteiras (bastante texto, com aspas e quebras de
// linha) — montar isso como string JS normal e mandar via
// this.helpers.httpRequest é muito mais seguro contra erro de escaping
// do que tentar encaixar tudo numa expressão de body JSON de um node.
//
// Segredo: OPENAI_API_KEY vem de uma variável de ambiente do container
// ($env), definida no .env do Docker — Code node não anexa Credential
// pela UI.

const ESQUELETOS_CENAS = [
  {
    nome: '1-foto-principal',
    regras_fixas: 'Foto principal/capa do anúncio. Produto ocupando OBRIGATORIAMENTE cerca de 80% da área da imagem, fundo branco puro (#FFFFFF), still de estúdio, luz suave e uniforme, sem sombra dura, altíssima fidelidade aos detalhes reais do produto (cor, forma, textura, rótulo). SEM texto sobreposto, SEM elemento gráfico extra — é a foto \'limpa\' de catálogo. Não adicionar acessório, marca ou função inexistente. Quadrado 1:1.',
    is_cover: true
  },
  {
    nome: '2-problema-que-resolve',
    regras_fixas: 'Cena publicitária quadrada que comunica visualmente O PROBLEMA/A DOR que esse produto resolve (ex: dificuldade, esforço, incômodo do dia a dia relacionado à categoria do produto) — SEM o produto em cena, ou com o produto discretamente à margem. Incluir um texto curto ON-IMAGE (título de 3-6 palavras) nomeando o problema, de forma honesta e baseada só no que é plausível pra essa categoria de produto (não inventar estatística, nem alegar um problema que o produto não resolve de fato). Tom visual de campanha, iluminação profissional. Texto em português correto, sem erro de ortografia. Quadrado 1:1.'
  },
  {
    nome: '3-beneficios-principais',
    regras_fixas: 'Cartaz de benefícios quadrado, título grande de impacto no topo. Abaixo, 3-4 blocos com ícone line-icon + frase curta QUALITATIVA descrevendo um benefício real do produto (nunca número/medida/certificação inventada) — ESSE TEXTO PRECISA ESTAR ESCRITO NA IMAGEM, grande e legível, não só sugerido visualmente. Produto em destaque visual (grande, bem iluminado). Paleta coerente com a categoria. Texto em português correto. Quadrado 1:1.'
  },
  {
    nome: '4-como-funciona',
    regras_fixas: 'Infográfico técnico premium quadrado, mostrando o produto sendo usado corretamente. EXATAMENTE 3 colunas verticais isoladas (sem nenhum elemento cruzando entre colunas), numeradas 01/02/03, cada uma com no máximo 1 mão humana interagindo com o produto. Título \'COMO FUNCIONA\' sem acento, grande, ON-IMAGE. Uma palavra curta em caixa alta abaixo de cada coluna (sem acentuação, ortografia revisada). Mãos adultas realistas, sem deformação. Não inventar peças/funções. Texto em português correto. Quadrado 1:1.'
  },
  {
    nome: '5-detalhes-premium',
    regras_fixas: 'Still de close-up/macro quadrado, mostrando com riqueza de detalhe o acabamento, material e textura REAIS do produto (zoom em uma parte específica visível na foto de referência — nunca inventar um detalhe que não está lá). 2-3 linhas de chamada finas apontando pra características visíveis, com rótulo curto e QUALITATIVO ESCRITO NA IMAGEM (ex: \'acabamento resistente\', \'encaixe preciso\') — nunca número/medida/certificação inventada. Iluminação de estúdio, fundo neutro. Texto em português correto. Quadrado 1:1.'
  },
  {
    nome: '6-pessoa-real-usando',
    regras_fixas: 'Fotografia publicitária realista de uma pessoa real (adulta, anatomicamente correta, mãos sem deformação) usando o produto em sua função real, ambiente coerente com a categoria, luz natural, enquadramento fechado na interação pessoa-produto. Não inventar peça ou função. Sem texto sobreposto nesta cena (o objetivo aqui é transmitir confiança/realismo, não informação escrita). Quadrado 1:1.'
  },
  {
    nome: '7-comparacao-antes-depois',
    regras_fixas: 'Imagem quadrada dividida em 2 metades lado a lado (SEM sobreposição entre as metades). Lado esquerdo: cenário representando a dificuldade/situação SEM o produto (rotulado \'ANTES\' ou \'SEM\', em português, ON-IMAGE, texto pequeno e discreto). Lado direito: mesma situação já resolvida COM o produto em uso (rotulado \'DEPOIS\' ou \'COM\'). NÃO alegar percentuais, tempo economizado ou qualquer resultado quantificado — é uma comparação qualitativa de situação, não uma alegação de performance mensurável. Linha divisória nítida entre os dois lados. Texto em português correto. Quadrado 1:1.'
  },
  {
    nome: '8-medidas-reais',
    regras_fixas: 'Imagem quadrada de referência de tamanho do produto. SE E SOMENTE SE a descrição do produto fornecida abaixo contiver uma medida/dimensão real confirmada, mostrar um diagrama com linhas de medida e ESSE NÚMERO REAL escrito ON-IMAGE. SE NÃO houver medida real confirmada na descrição, NÃO INVENTAR NENHUM NÚMERO — em vez disso, gerar uma \'referência de escala visual\': o produto posicionado ao lado de um objeto cotidiano comum e reconhecível (ex: uma mão humana, um celular, uma moeda — escolha o que for proporcionalmente coerente com o tamanho provável da categoria do produto), sem nenhum número impresso, só a comparação visual de tamanho. Fundo neutro, iluminação de estúdio. Texto em português correto (se houver). Quadrado 1:1.'
  }
];

const nomeProduto = $('preparar-para-imagens').first().json.nome_produto;
const tituloGerado = $('preparar-para-imagens').first().json.generated_title;
const descricaoGerada = $('preparar-para-imagens').first().json.generated_description;
const descricaoProduto = `Título do anúncio: ${tituloGerado}\n\nDescrição do anúncio:\n${descricaoGerada}`;

const esqueletosTexto = ESQUELETOS_CENAS
  .map(c => `CENA "${c.nome}": ${c.regras_fixas}`)
  .join('\n\n');

const instrucao = `Você escreve prompts de geração de imagem para o modelo Gemini (Google), para anúncios de e-commerce no Mercado Livre.

Produto: ${nomeProduto}
Descrição real do produto (use como base factual, não invente além disso — inclua aqui qualquer medida/dimensão real que você souber, pra cena 8 poder usá-la; se não souber nenhuma medida real, não invente):
${descricaoProduto}

Abaixo estão 8 "esqueletos" de cena, na ORDEM EXATA em que devem aparecer no anúncio, cada um com REGRAS FIXAS já calibradas em testes anteriores para evitar bugs visuais conhecidos (objetos se fundindo, texto com erro de ortografia, dados numéricos inventados, selos de certificação falsos). Sua tarefa: para cada cena, escrever um prompt final em português, específico para ESTE produto (usando a descrição real acima), MANTENDO INTEGRALMENTE todas as regras fixas listadas — você pode adicionar detalhes específicos do produto, mas NUNCA remover ou enfraquecer uma regra fixa, e NUNCA inventar número/medida/certificação que não esteja na descrição fornecida.

REGRA GERAL IMPORTANTE (vale pra todas as cenas que pedem texto on-image): o texto/dado central de cada cena precisa aparecer ESCRITO DE FORMA VISÍVEL NA PRÓPRIA IMAGEM, não apenas sugerido visualmente — feedback real de uso mostrou que o comprador absorve muito mais informação do texto embutido na imagem do que da legenda separada.

${esqueletosTexto}

Responda em JSON, formato exato:
{"cenas": [{"nome": "...", "prompt_final": "..."}, ...]}
Uma entrada por cena, na mesma ordem, usando o mesmo "nome" de cada uma.`;

const resposta = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://api.openai.com/v1/chat/completions',
  headers: {
    Authorization: `Bearer ${$env.OPENAI_API_KEY}`,
    'Content-Type': 'application/json'
  },
  body: {
    model: 'gpt-4.1',
    messages: [{ role: 'user', content: instrucao }],
    response_format: { type: 'json_object' }
  },
  json: true
});

const dados = JSON.parse(resposta.choices[0].message.content);
const prompts = {};
for (const c of dados.cenas) { prompts[c.nome] = c.prompt_final; }

return [{ json: { prompts } }];

// =====================================================================
// preparar-regeneracao — entrada da regeneração de 1 imagem específica
// (botão 🔄 Refazer imagem → lista Imagem 1..8). Traduz o lista_id
// ("refazer_3") no nome da cena e recupera listing_id/URL da foto original
// do conversation_context do vendedor (gravados em atualizar-estado-aprovacao).
// =====================================================================
//
// Só os NOMES das 8 cenas, na mesma ordem de montar-itens-cenas — as
// regras_fixas não são necessárias aqui, o prompt final já foi salvo em
// listings.scene_prompts por salvar-scene-prompts na geração original.
const NOMES_CENAS = [
  '1-foto-principal',
  '2-problema-que-resolve',
  '3-beneficios-principais',
  '4-como-funciona',
  '5-detalhes-premium',
  '6-pessoa-real-usando',
  '7-comparacao-antes-depois',
  '8-medidas-reais'
];

const listaId = $('parse-mensagem').first().json.lista_id ?? '';
const indice = parseInt(listaId.replace('refazer_', ''), 10) - 1;
const scene = NOMES_CENAS[indice];

if (!scene) {
  throw new Error(`lista_id "${listaId}" não corresponde a nenhuma das 8 cenas (esperava "refazer_1".. "refazer_8").`);
}

const contexto = $('buscar-vendedor').first().json.conversation_context ?? {};

return [{
  json: {
    scene,
    listing_id: contexto.listing_id,
    original_photo_storage_url: contexto.original_photo_storage_url
  }
}];

// =====================================================================
// montar-item-cena-regeneracao — equivalente a montar-itens-cenas, mas monta
// só 1 item (a cena escolhida), usando o prompt já salvo em vez de rechamar
// o GPT. Alimenta o MESMO gerar-foto-cena da geração original.
// =====================================================================
const meta = $('preparar-regeneracao').first().json;
const promptFinal = $json.prompt_final;

if (!promptFinal) {
  throw new Error(`Não encontrei prompt salvo para a cena "${meta.scene}" — esse anúncio provavelmente foi gerado antes do recurso de refazer imagem existir (scene_prompts vazio).`);
}

const fotoConvertida = $('converter-foto-base64').first().json;
const promptCompleto = `Usando a imagem de referência do produto anexada, gere uma nova foto do MESMO produto exato (preserve rigorosamente cor, formato, proporções, rótulos e texturas reais do objeto — não invente detalhes que o produto não tem). ${promptFinal}`;

return [{
  json: {
    scene: meta.scene,
    is_cover: meta.scene === '1-foto-principal',
    listing_id: meta.listing_id,
    prompt_completo: promptCompleto,
    foto_base64: fotoConvertida.foto_base64,
    foto_mime: fotoConvertida.foto_mime
  }
}];

// =====================================================================
// montar-itens-cenas — monta os 8 items (um por cena) que alimentam o node
// gerar-foto-cena. NÃO faz chamada HTTP.
// =====================================================================
const ESQUELETOS_CENAS = [
  {
    nome: '1-foto-principal',
    regras_fixas: 'Foto principal/capa do anúncio. Produto ocupando OBRIGATORIAMENTE cerca de 80% da área da imagem, fundo branco puro (#FFFFFF), still de estúdio, luz suave e uniforme, sem sombra dura, altíssima fidelidade aos detalhes reais do produto (cor, forma, textura, rótulo). SEM texto sobreposto, SEM elemento gráfico extra — é a foto \'limpa\' de catálogo. Não adicionar acessório, marca ou função inexistente. Quadrado 1:1.',
    is_cover: true
