const promptsPorNome = $('gerar-prompts-gpt').first().json.prompts;
const fotoConvertida = $('converter-foto-base64').first().json;
const fotoBase64 = fotoConvertida.foto_base64;
const fotoMime = fotoConvertida.foto_mime;
const listingId = $('preparar-para-imagens').first().json.listing_id;

if (!fotoBase64) {
  throw new Error('converter-foto-base64 não devolveu foto_base64 — confira se esse node está antes de montar-itens-cenas na execução.');
}

return ESQUELETOS_CENAS.map(esqueleto => {
  const promptFinal = promptsPorNome[esqueleto.nome];
  if (!promptFinal) {
    throw new Error(`GPT não devolveu prompt para a cena "${esqueleto.nome}"`);
  }
  const promptCompleto = `Usando a imagem de referência do produto anexada, gere uma nova foto do MESMO produto exato (preserve rigorosamente cor, formato, proporções, rótulos e texturas reais do objeto — não invente detalhes que o produto não tem). ${promptFinal}`;
  return {
    json: {
      scene: esqueleto.nome,
      is_cover: !!esqueleto.is_cover,
      listing_id: listingId,
      prompt_completo: promptCompleto,
      foto_base64: fotoBase64,
      foto_mime: fotoMime
    },
    pairedItem: { item: 0 }
  };
});

// =====================================================================
// extrair-imagem-cena — transforma as respostas JSON do Gemini nos items
// binários que o upload pro Storage espera. Compartilhado por 2 fluxos:
// geração original (8 cenas, vindas de montar-itens-cenas) e regeneração
// de 1 imagem (botão 🔄 Refazer imagem, vinda de montar-item-cena-regeneracao)
// — só um dos dois roda em cada execução, nunca os dois.
// =====================================================================
//
// Só manipula JSON e devolve binário no formato nativo do n8n (string
// base64 em `data`) — não faz chamada HTTP e não monta Buffer, então não
// esbarra em nenhuma das limitações do Task Runner.
//
// O casamento com a cena é POR ÍNDICE contra a origem (8 ou 1 item): o node
// de geração roda um request por item, na ordem, e está com "Continue On
// Fail" desligado, então ou vêm as respostas na mesma ordem ou a execução
// para antes de chegar aqui. A checagem de contagem abaixo garante isso.

function tentarPegar(nomeDoNode) {
  try {
    return $(nomeDoNode).all();
  } catch (e) {
    return [];
  }
}

const cenasRegeneracao = tentarPegar('montar-item-cena-regeneracao');
const ehRegeneracao = cenasRegeneracao.length > 0;
const cenas = ehRegeneracao ? cenasRegeneracao : $('montar-itens-cenas').all();
const respostas = $input.all();

if (respostas.length !== cenas.length) {
  throw new Error(
    `Esperava ${cenas.length} respostas do Gemini, recebi ${respostas.length}.`
  );
}

return respostas.map((item, i) => {
  const meta = cenas[i].json;
  const resposta = item.json;

  const partes = resposta?.candidates?.[0]?.content?.parts ?? [];
  const parteImagem = partes.find(p => p.inlineData || p.inline_data);
  const inline = parteImagem?.inlineData ?? parteImagem?.inline_data;

  if (!inline) {
    throw new Error(
      `Gemini não retornou imagem para a cena "${meta.scene}": ${JSON.stringify(resposta).slice(0, 500)}`
    );
  }

  return {
    json: { scene: meta.scene, is_cover: meta.is_cover, listing_id: meta.listing_id, is_regeneracao: ehRegeneracao },
    binary: {
      imagem: {
        data: inline.data,
        mimeType: inline.mimeType ?? inline.mime_type ?? 'image/png',
        fileName: `${meta.scene}.png`
      }
    },
    pairedItem: { item: i }
  };
});

// =====================================================================
// montar-lista-fotos-storage — junta os 8 uploads de volta num único item,
// no formato que atualizar-listing-fotos e os envio-foto-1..8 esperam:
//   { listing_id, generated_photos: [{ url, scene, is_cover }, ...] }
// =====================================================================
//
// Este node NÃO faz upload — quem sobe é o HTTP Request nativo anterior
// (upload-fotos-storage). Ver a nota daquele node: Buffer dentro de Code
// node não sobrevive ao RPC do Task Runner.
//
// A URL pública é previsível, então é montada por string; o caminho vem do
// campo `Key` da resposta do Supabase ("<bucket>/<caminho>") sempre que
// disponível, que é o que de fato foi gravado.
//
// scene/is_cover são relidos de extrair-imagem-cena e casados PELO
// NOME DA CENA (não por índice) — o node de upload devolve um item por
// upload e não carrega o json de entrada adiante.

const SUPABASE_URL = $env.SUPABASE_URL;
const BUCKET = $env.SUPABASE_STORAGE_BUCKET || 'listing-photos';
const listingId = $('preparar-para-imagens').first().json.listing_id;

const cenas = $('extrair-imagem-cena').all().map(i => i.json);
const metaPorCena = {};
for (const c of cenas) { metaPorCena[c.scene] = c; }

const generatedPhotos = $input.all().map((item, i) => {
  const key = item.json?.Key ?? item.json?.key ?? null;
  let caminho;
  if (key) {
    caminho = key.startsWith(BUCKET + '/') ? key.slice(BUCKET.length + 1) : key;
  } else {
    caminho = `${listingId}/${cenas[i].scene}.png`;
  }

  const scene = caminho.split('/').pop().replace('.png', '');
  const meta = metaPorCena[scene] ?? cenas[i] ?? {};

  return {
    url: `${SUPABASE_URL}/storage/v1/object/public/${BUCKET}/${caminho}`,
    scene,
    is_cover: !!meta.is_cover
  };
});

if (generatedPhotos.length !== cenas.length) {
  throw new Error(
    `Esperava ${cenas.length} uploads, recebi ${generatedPhotos.length} — alguma cena não subiu pro Storage.`
  );
}

// Ordena pelo prefixo numérico do nome da cena (1-... a 8-...): os nodes
// envio-foto-1..8 leem generated_photos[0..7] por índice, então a ordem de
// chegada no WhatsApp depende disso, não da ordem em que os uploads terminaram.
generatedPhotos.sort((a, b) => a.scene.localeCompare(b.scene));

return [{ json: { listing_id: listingId, generated_photos: generatedPhotos } }];

