// Compartilhado por 2 fluxos (geração original das 8 fotos e regeneração de
// 1 imagem) — is_regeneracao marca qual dos dois é, pra verificar-modo-geracao
// decidir se chama gerar-prompts-gpt (GPT) de novo ou pula direto pra
// buscar-scene-prompt (reaproveita o prompt já salvo, sem chamar o GPT).
let ehRegeneracao = false;
try {
  ehRegeneracao = $('preparar-regeneracao').all().length > 0;
} catch (e) {
  ehRegeneracao = false;
}

const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const mimeType = $input.first().binary.data.mimeType || 'image/jpeg';

return [{
  json: {
    ...$input.first().json,
    foto_base64: buffer.toString('base64'),
    foto_mime: mimeType,
    is_regeneracao: ehRegeneracao
  }
}];

